def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Finds the shortest path in a weighted directed graph using the Floyd-Warshall algorithm.
    Returns the shortest distance and the path as a list of node names.
    """
    nodes = list(graph.keys())
    n = len(nodes)
    distance = {node: {other: float('inf') for other in nodes} for node in nodes}
    next_node = {node: {other: None for other in nodes} for node in nodes}

    for node in nodes:
        distance[node][node] = 0

    for node in nodes:
        for neighbor, weight in graph[node]:
            distance[node][neighbor] = weight
            next_node[node][neighbor] = neighbor

    for k in nodes:
        for i in nodes:
            for j in nodes:
                if distance[i][j] > distance[i][k] + distance[k][j]:
                    distance[i][j] = distance[i][k] + distance[k][j]
                    next_node[i][j] = next_node[i][k]

    if distance[start][end] == float('inf'):
        return (float('inf'), [])

    path = []
    current_node = start
    while current_node is not None:
        path.append(current_node)
        current_node = next_node[current_node][end] if current_node != end else None

    return (distance[start][end], path)

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Finds the shortest path in a weighted directed graph using a modified breadth-first search (BFS) approach.
    This implementation utilizes a queue to explore all nodes at the current depth before moving deeper.
    It keeps track of weights and paths to find the minimum distance.
    """
    from collections import deque

    if start not in graph or end not in graph:
        return (float('inf'), [])

    queue = deque([(start, 0)])  # (current_node, current_distance)
    visited = {node: (float('inf'), None) for node in graph}  # node: (distance, predecessor)
    visited[start] = (0, None)

    while queue:
        current_node, current_distance = queue.popleft()

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < visited[neighbor][0]:
                visited[neighbor] = (distance, current_node)
                queue.append((neighbor, distance))

    min_distance, predecessor = visited[end]

    if min_distance == float('inf'):
        return (float('inf'), [])

    path = []
    while predecessor is not None:
        path.append(predecessor)
        predecessor = visited[predecessor][1]

    path.reverse()
    path.append(end)

    return (min_distance, path)
